executor/claudecode/claudecode.go.patch:
--- a/executor/claudecode/claudecode.go
+++ b/executor/claudecode/claudecode.go
@@ -549,11 +549,11 @@
 		return authInfo{}, classify(ctx)
 	}
 	var info authInfo
-	if err := json.Unmarshal(out, &info); err != nil {
+	if err := json.Unmarshal(out, &info); err != nil || !bytes.HasPrefix(bytes.TrimSpace(out), []byte("{")) {
 		if runErr != nil {
 			return info, executor.Fail(executor.ReasonUnavailable, "`claude auth status --json` failed; "+kogenLogin)
 		}
-		return info, executor.Fail(executor.ReasonAuthRefused, "`claude auth status --json` did not answer with JSON")
+		return info, executor.Fail(executor.ReasonUnavailable, unreadableStatusDetail(a.redact(string(out))))
 	}
 	switch {
 	case !info.LoggedIn && a.opts.Token != "":
@@ -569,6 +569,15 @@
 		return info, executor.Fail(executor.ReasonUnavailable, "`claude auth status --json` failed; "+kogenLogin)
 	}
 	return info, nil
+}
+
+// unreadableStatusDetail names a status answer that is not a JSON object and quotes a bounded excerpt of it.
+func unreadableStatusDetail(printed string) string {
+	printed = strings.TrimSpace(printed)
+	if printed == "" {
+		return "`claude auth status --json` status answer was unreadable: it was empty"
+	}
+	return "`claude auth status --json` status answer was unreadable (not a JSON object); it printed: " + strconv.Quote(bound(printed, 200))
 }

